from AlgorithmImports import *
from datetime import datetime, timedelta, time, date


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-100, 100)
                       .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None
        self.expiration_processed = set()

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._process_expiration_safety(today)
        self._process_time_stop(now)

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._process_profit_target(slice)

        if self.entry_ticket is not None and not self._is_open(self.entry_ticket):
            self.entry_ticket = None

        if self.exit_ticket is not None and not self._is_open(self.exit_ticket):
            self.exit_ticket = None

        if not getattr(self, "entry_signal", False):
            return

        self.entry_signal = False

        if self.expiration_block_date == today:
            return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{now}: skipped entry; no option chain.")
            return

        algorithm_date = today
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not eligible:
            self.Debug(f"{now}: skipped entry; no expiration at least 7 calendar days out.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        spy_price = self.Securities[self.spy_symbol].Price
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{now}: skipped entry; no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        symbol = order_event.Symbol

        if self.entry_ticket is not None and symbol == self.entry_symbol:
            self.entry_price = order_event.FillPrice
            self.Debug(
                f"{self.Time}: entered {symbol} at filled price "
                f"{self.entry_price:.4f}"
            )
            return

        if self.exit_ticket is not None and symbol == self.entry_symbol:
            self.Debug(
                f"{self.Time}: exited {symbol} at filled price "
                f"{order_event.FillPrice:.4f}"
            )
            self.entry_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            return

        if order_event.Direction == OrderDirection.Sell and symbol == self.entry_symbol:
            self.Debug(
                f"{self.Time}: unexpected exercise or assignment handling "
                f"for {symbol}"
            )
            self.entry_symbol = None
            self.entry_price = None
            self.exit_ticket = None

    def OnEndOfAlgorithm(self):
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self.Debug(f"{self.Time}: unexpected open option position at algorithm end.")

    def OnDataConsolidated(self, sender, bar):
        pass

    def OnSecuritiesChanged(self, changes):
        pass

    def _update_five_minute_bar(self, minute_bar):
        if minute_bar.Symbol != self.spy_symbol:
            return

        bar_time = minute_bar.EndTime
        local_time = bar_time.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        start_minute = ((bar_time.minute - 30) // 5) * 5 + 30
        bucket_start = bar_time.replace(
            minute=start_minute,
            second=0,
            microsecond=0
        )

        if self.current_bucket != bucket_start:
            self.current_bucket = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = minute_bar

        expected = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if not all(t in self.bucket_bars for t in expected):
            return

        if bar_time != expected[-1]:
            return

        close = self.bucket_bars[expected[-1]].Close
        self.closes.append(float(close))
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) >= self.slow_period:
            fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            slow = sum(self.closes[-self.slow_period:]) / self.slow_period

            if self.previous_fast is not None and self.previous_slow is not None:
                bullish = (
                    self.previous_fast <= self.previous_slow
                    and fast > slow
                )

                end_time = bar_time.time()
                eligible_time = time(9, 45) <= end_time <= time(14, 30)

                if bullish and eligible_time:
                    self.entry_signal = True

            self.previous_fast = fast
            self.previous_slow = slow

    def _process_profit_target(self, slice: Slice):
        if self.entry_price is None or self.exit_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (c for c in chain if c.Symbol == self.entry_symbol),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_time_stop(self, now):
        if self.entry_symbol is None or self.exit_ticket is not None:
            return

        security = self.Securities[self.entry_symbol]
        expiry_date = security.Symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if now.date() == previous_trading_day and now.time() >= time(15, 45):
            self._submit_exit("expiration time stop")

    def _process_expiration_safety(self, today):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()
        if today < expiry_date:
            return

        if expiry_date in self.expiration_processed:
            return

        self.expiration_processed.add(expiry_date)
        self.expiration_block_date = today

        if self.Portfolio[self.entry_symbol].Invested and self.exit_ticket is None:
            self._submit_exit("expiration safety liquidation")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        if self.Portfolio[self.entry_symbol].Invested:
            quantity = -self.Portfolio[self.entry_symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(self.entry_symbol, quantity)
                self.Debug(f"{self.Time}: submitted exit for {reason}.")

    def _previous_trading_day(self, target_date):
        current = target_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(current):
            current -= timedelta(days=1)

        return current

    @staticmethod
    def _is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnData(self, slice: Slice):
        minute_bar = slice.Bars.get(self.spy_symbol)
        if minute_bar is not None:
            self._update_five_minute_bar(minute_bar)

        self._handle_slice(slice)

    def _handle_slice(self, slice):
        now = self.Time
        today = now.date()

        self._process_expiration_safety(today)
        self._process_time_stop(now)

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            self._process_profit_target(slice)

        if self.entry_signal:
            self.entry_signal = False
            self._try_entry(slice)

    def _try_entry(self, slice):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return
        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug(f"{self.Time}: skipped entry; no option chain.")
            return

        eligible = [
            c for c in chain
            if c.Right == OptionRight.Call
            and (c.Expiry.date() - today).days >= 7
        ]

        if not eligible:
            self.Debug(f"{self.Time}: skipped entry; no valid expiration.")
            return

        expiry = min(c.Expiry.date() for c in eligible)
        minimum_strike = 1.01 * self.Securities[self.spy_symbol].Price

        candidates = [
            c for c in eligible
            if c.Expiry.date() == expiry and c.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: skipped entry; no qualifying call.")
            return

        contract = sorted(candidates, key=lambda c: (c.Strike, str(c.Symbol)))[0]
        self.entry_symbol = contract.Symbol
        self.entry_price = None
