from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self._previous_fast = None
        self._previous_slow = None
        self._signal_ready = False
        self._signal_time = None

        self._held_symbol = None
        self._entry_ticket = None
        self._exit_ticket = None
        self._entry_price = None
        self._expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Do not intentionally carry an option into its expiration date.
        if self._held_symbol is not None:
            expiry = self._held_symbol.ID.Date.date()

            if current_date >= expiry:
                self._expiration_block_date = current_date
                self._SubmitExit("expiration processing")
            elif self._IsPreExpirationTradingDay(expiry, current_date):
                if self.Time.hour > 15 or (
                    self.Time.hour == 15 and self.Time.minute >= 45
                ):
                    self._SubmitExit("expiration time stop")

        # Evaluate the target on every minute Slice using the current quote.
        if self._held_symbol is not None and self._entry_price is not None:
            contract = self._GetCurrentContract(slice, self._held_symbol)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self._entry_price:
                        self._SubmitExit("50% profit target")

        # The consolidator emits only actual consolidated bars.
        self.consolidator.Update(slice)

        if (
            self._signal_ready
            and self._signal_time == self.Time
            and self._IsEligibleEntryTime()
        ):
            self._signal_ready = False
            self._TryEnter(slice)
        elif self._signal_ready and self._signal_time != self.Time:
            self._signal_ready = False

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        self._previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self._previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and self._previous_fast <= self._previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        ):
            self._signal_ready = True
            self._signal_time = bar.EndTime

    def _TryEnter(self, slice: Slice):
        if self._expiration_block_date == self.Time.date():
            return

        if self._held_symbol is not None:
            return

        if (
            self._entry_ticket is not None
            and self._entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            )
        ):
            return

        chains = slice.OptionChains
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        eligible_expirations = []

        for chain in chains.Values:
            for contract in chain:
                expiry = contract.Expiry.date()
