        self.spy_option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self.current_bucket = None
        self.bucket_bars = []
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_submitted = False
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into its expiration date.
        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if today >= expiration_date:
                self.expiration_block_date = today
                self._liquidate_held_option("expiration processing")
            elif (
                today == expiration_date - timedelta(days=1)
                and self.Time.time() >= time(15, 45)
                and not self.time_stop_submitted
            ):
                self._liquidate_held_option("pre-expiration time stop")
                self.time_stop_submitted = True

        self._process_minute_bar(slice)

        if self.pending_signal:
            self.pending_signal = False
            self._try_enter(slice)

        self._evaluate_profit_target(slice)

    def _process_minute_bar(self, slice: Slice):
        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        bar_time = bar.EndTime
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if bar_clock < time(9, 31) or bar_clock > time(16, 0):
            return

        # Minute bars are timestamped at their ending minute. The first
        # regular-session five-minute bar ends at 09:35.
        minute_index = bar_time.hour * 60 + bar_time.minute
        bucket_index = minute_index // 5
        bucket = (bar_date, bucket_index)

        if self.current_bucket is None:
            self.current_bucket = bucket

        if bucket != self.current_bucket:
            self._complete_bucket()

            self.current_bucket = bucket
            self.bucket_bars = []

        self.bucket_bars.append(bar)

    def _complete_bucket(self):
        if not self.bucket_bars:
            return

        first = self.bucket_bars[0]
        last = self.bucket_bars[-1]

        # Require every minute in the five-minute interval. Do not fill gaps.
        expected_times = {
            first.EndTime - timedelta(minutes=i)
            for i in range(len(self.bucket_bars))
        }
        actual_times = {bar.EndTime for bar in self.bucket_bars}

        if len(self.bucket_bars) != 5 or expected_times != actual_times:
            self.bucket_bars = []
            return

        close = float(last.Close)
        self.fast_window.Add(close)
        self.slow_window.Add(close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            self.bucket_bars = []
            return

        fast_current = sum(self.fast_window[i] for i in range(5)) / 5.0
        slow_current = sum(self.slow_window[i] for i in range(20)) / 20.0

        if self.fast_window.Count < 6 or self.slow_window.Count < 21:
            self.bucket_bars = []
            return

        fast_previous = sum(self.fast_window[i] for i in range(1, 6)) / 5.0
        slow_previous = sum(self.slow_window[i] for i in range(1, 21)) / 20.0

        bar_end = last.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if (
            eligible_time
            and fast_previous <= slow_previous
            and fast_current > slow_current
        ):
            self.pending_signal = True

        self.bucket_bars = []

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_price = float(self.Securities[self.spy].Price)
        if current_price <= 0:
            self.Debug("Skipped entry: invalid current SPY price.")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Symbol.ID.OptionStyle != OptionStyle.American:
                    pass
                contracts.append(contract)

        eligible_expirations = sorted({
            contract.Symbol.ID.Date.date()
            for contract in contracts
            if contract.Symbol.ID.Date.date() >= today + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiration = eligible_expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Symbol.ID.Date.date() == expiration
            and contract.Symbol.ID.OptionType == Option right.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (
            float(contract.Strike),
            str(contract.Symbol)
        ))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted entry for {}".format(selected.Symbol))

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        held_symbol = self.held_option.Symbol
        contract = None

        for chain in slice.OptionChains.Values:
            if held_symbol in chain:
                contract = chain[held_symbol]
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._liquidate_held_option("50% profit target")

    def _liquidate_held_option(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        if self.entry_ticket is not None and not self.entry_ticket.Status.IsClosed():
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option.Symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Submitted exit for {}: {}".format(
            self.held_option.Symbol, reason
        ))

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)
                self.time_stop_submitted = False
                self.Debug("Entry filled: {} at {}".format(
                    order_event.Symbol, order_event.FillPrice
                ))
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                if order_event.Status != OrderStatus.None_:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {}".format(
                    order_event.Symbol, order_event.FillPrice
                ))
                self.held_option = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected exercise or assignment handling: {}".format(
                assignment_event
            )
        )
