        quantity = -self.Portfolio[self._held_option].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(
                self._held_option,
                quantity
            )
            self.Debug(
                "Exit submitted ({}): {}".format(
                    reason,
                    self._held_option
                )
            )

    def _cancel_other_exit_orders(self):
        if self._exit_ticket is not None and not self._exit_ticket.Status.IsClosed():
            self._exit_ticket.Cancel("Replaced by liquidation order")
            self._exit_ticket = None

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
