        return candidate

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.Debug(
            "Unexpected option exercise or assignment: {}".format(
                assignment_event
            )
        )

        if self._held_option is not None:
            self._liquidate_held_option("unexpected assignment handling")
