                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiry_date = None
        self.expiration_processed_date = None

        # Buckets keyed by five-minute interval end time.
        self.minute_buckets = defaultdict(dict)

        self.SetWarmUp(0)

    def OnData(self, slice: Slice):
        now = self.Time
        local_date = now.date()
        local_time = now.time()

        self._process_expiration_safety(slice, local_date)
        self._process_time_stop(local_date, local_time)
        self._process_profit_target(slice)

        if self.entry_ticket is not None:
            return

        if self._has_option_holding():
            return

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._process_spy_minute(bar)

    def _process_spy_minute(self, bar: TradeBar):
        end_local = bar.EndTime.astimezone(self.TimeZone)
        session_start = time(9, 30)
        session_end = time(16, 0)

        if end_local.time() <= session_start or end_local.time() > session_end:
            return

        minute = end_local.replace(second=0, microsecond=0)
        interval_end_minute = minute.replace(
            minute=(minute.minute // 5) * 5
        )

        if minute.minute % 5 != 0:
            interval_end_minute += timedelta(minutes=5)

        interval_end = interval_end_minute
        bucket_key = interval_end

        self.minute_buckets[bucket_key][minute] = bar.Close

        # A five-minute bar is complete when its final minute has arrived.
        if minute.minute % 5 != 0:
            return

        bucket = self.minute_buckets.pop(bucket_key, {})
        expected = [
            interval_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(m not in bucket for m in expected):
            return

        close = bucket[expected[-1]]
        self._process_five_minute_close(close, interval_end)

    def _process_five_minute_close(self, close, bar_end):
        self.closes.append(float(close))
        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous = self.closes[:-1]
        current = self.closes

        previous_fast = sum(previous[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous[-self.slow_period:]) / self.slow_period
        current_fast = sum(current[-self.fast_period:]) / self.fast_period
        current_slow = sum(current[-self.slow_period:]) / self.slow_period

        end_time = bar_end.time()
        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        bullish = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        if bullish:
            self._try_enter_call()

    def _try_enter_call(self):
        if self.entry_ticket is not None or self._has_option_holding():
            return

        chain = None
        for candidate in self.CurrentSlice.OptionChains.Values:
            if candidate.Symbol == self.option_symbol:
