        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(
            key=lambda contract: (
                float(contract.ID.Strike),
                str(contract.Symbol)
            )
        )

        selected = candidates[0]
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish crossover")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_contract = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        f"Entry filled: {self.held_contract} "
                        f"at {self.entry_price:.4f}"
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol} "
                        f"at {order_event.FillPrice:.4f}"
                    )
                    self.exit_ticket = None
                    self.entry_ticket = None
                    self.held_contract = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def LiquidateHeldOption(self, reason):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_contract,
                -quantity,
                tag=reason
            )
            self.Debug(f"Exit submitted: {self.held_contract} ({reason})")

    def IsTradingDayImmediatelyBeforeExpiry(self, current_date, expiry_date):
        date = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(date):
            date -= timedelta(days=1)

        return current_date == date

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            f"Unexpected option assignment/exercise handling: "
            f"{assignment_event}"
        )
        self.block_entries_today = True
