            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._block_start = None
        self._minute_bars = []
        self._previous_fast = None
        self._previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None
        self._expiration_handled_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)

        if self.held_symbol is not None:
            self._evaluate_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        if self._is_regular_session(spy_bar.EndTime):
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.EndTime
        minute = local_time.minute
        block_minute = minute - (minute % 5)
        block_start = local_time.replace(
            minute=block_minute, second=0, microsecond=0
        )

        if self._block_start != block_start:
            self._block_start = block_start
            self._minute_bars = []

        self._minute_bars.append(bar)

        if len(self._minute_bars) < 5:
            return

        bars = self._minute_bars
        self._minute_bars = []

        expected_times = [
            block_start + timedelta(minutes=i) for i in range(5)
        ]
        actual_times = [b.Time for b in bars]

        if actual_times != expected_times:
            return

        close = bars[-1].Close
        fast_value = self.fast.Current.Value if self.fast.IsReady else None
        slow_value = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, close)
        self.slow.Update(bar.EndTime, close)

        if fast_value is None or slow_value is None:
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            fast_value <= slow_value
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        bar_end_time = bar.EndTime.time()
        if not (time(9, 45) <= bar_end_time <= time(14, 30)):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_done(
            self.entry_ticket
        ):
            return

        chain = slice.OptionChains.get(self.option)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        algorithm_date = self.Time.date()
        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - algorithm_date).days >= 7
        ]

        if not eligible:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        expiration = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = 1.01 * spy_price
        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == expiration
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Call entry submitted: {selected.Symbol}; "
            f"strike={selected.Strike}; expiry={expiration}"
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and not self._ticket_done(
            self.exit_ticket
        ):
            return

        contract = slice.OptionChains.get(self.option)
        quote = None

        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_symbol:
                    quote = item
                    break

        if quote is not None:
            bid = quote.BidPrice
            ask = quote.AskPrice

            if (
                bid is not None and ask is not None
                and bid > 0 and ask > 0
                and self.entry_price is not None
            ):
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * self.entry_price:
                    self._submit_exit("50% profit target")
                    return

        if self._is_expiration_eve():
            self._submit_exit("expiration-eve time stop")

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry:
            if self._expiration_handled_date != current_date:
                self._expiration_handled_date = current_date
                self._submit_exit("expiration protection")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_done(
            self.exit_ticket
        ):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity, tag=reason
        )
        self.Debug(f"Call exit submitted: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status != OrderStatus.Filled:
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.expiration_block_date = (
                self.Securities[self.held_symbol].Symbol.ID.Date.date()
            )
            self.Debug(
                f"Call entry filled: {self.held_symbol}; "
                f"price={self.entry_price}"
            )

        elif (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            self.Debug(
                f"Call exit filled: {order_event.Symbol}; "
                f"price={order_event.FillPrice}"
            )
            if not self.Portfolio[order_event.Symbol].Invested:
                self.held_symbol = None
                self.entry_price = None
                self.expiration_block_date = None
                self.exit_ticket = None
                self.entry_ticket = None

        if order_event.Symbol.SecurityType == SecurityType.Option:
            if order_event.Message and (
                "exercise" in order_event.Message.lower()
                or "assignment" in order_event.Message.lower()
            ):
                self.Debug(
                    f"Unexpected option exercise or assignment: "
                    f"{order_event.Symbol}"
                )

    def OnAssignmentOrderEvent(self, assignment_order_event):
        self.Debug(
            f"Unexpected option assignment handling: "
            f"{assignment_order_event}"
        )

    def _is_expiration_eve(self):
        if self.expiration_block_date is None:
            return False

        if self.Time.time() < time(15, 45):
            return False

        expiration = self.expiration_block_date
        date = self.Time.date() + timedelta(days=1)

        while date < expiration:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(date):
                return self.Time.date() == date - timedelta(days=1)
            date += timedelta(days=1)

        return False

    def _is_regular_session(self, end_time: datetime):
        current = end_time.time()
        return time(9, 30) < current <= time(16, 0)

    @staticmethod
    def _ticket_done(ticket):
        return ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled,
        )
