from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._five_minute_bars = []
        self._last_consolidated_end = None
        self._pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self._expiration_liquidated_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        local_end = Extensions.ConvertTo(self.TimeZone, bar.EndTime)

        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        if self._last_consolidated_end is not None:
            if bar.EndTime - self._last_consolidated_end != timedelta(minutes=5):
                self._last_consolidated_end = bar.EndTime
                return

        self._last_consolidated_end = bar.EndTime

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
            and time(9, 45) <= local_end.time() <= time(14, 30)
        ):
            self._pending_signal = True

    def OnData(self, slice: Slice):
        self._process_expiration_safety(slice)

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            self._evaluate_profit_target(slice)

        if self._pending_signal:
            self._pending_signal = False
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        if slice.OptionChains is None or len(slice.OptionChains) == 0:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        chain = None
        for candidate in slice.OptionChains:
            if candidate.Key.SecurityType == SecurityType.Option:
                chain = candidate.Value
                break

        if chain is None or len(chain) == 0:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= algorithm_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped selection: no expiration at least seven calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        spy_price = self.Securities[self.spy].Price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiration {1}, strike {2}".format(
                selected.Symbol, selected.Expiry.date(), selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        if self.held_symbol not in slice.Bars:
            quote = slice.QuoteBars.get(self.held_symbol)
        else:
            quote = slice.QuoteBars.get(self.held_symbol)

        if quote is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_open_exit()
            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    self.held_symbol, -quantity, tag="50% profit target"
                )
                self.Debug("Exit submitted: 50% profit target.")

    def _process_expiration_safety(self, slice: Slice):
        if self.held_symbol is None:
            return

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return

        expiry_date = security.Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            if self.Portfolio[self.held_symbol].Invested:
                self._cancel_open_exit()
                quantity = self.Portfolio[self.held_symbol].Quantity
                if quantity != 0:
                    self.exit_ticket = self.MarketOrder(
                        self.held_symbol, -quantity, tag="expiration safety exit"
                    )
                    self.Debug("Exit submitted: expiration safety liquidation.")
            self._expiration_liquidated_date = current_date
            self._pending_signal = False
            return

        if self.Portfolio[self.held_symbol].Invested:
            previous_trading_day = expiry_date - timedelta(days=1)
            while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                previous_trading_day
            ):
                previous_trading_day -= timedelta(days=1)

            local_time = self.Time.time()
            if (
                current_date == previous_trading_day
                and local_time >= time(15, 45)
            ):
                self._cancel_open_exit()
